<?php
declare(strict_types=1);
require_once __DIR__.'/paid-functions.php';
function salariesApi(array $u,string $action,string $method,array $b):array{fullManager($u);$t=$u['tenant'];$frames=records($t,'salary_frames');$jobs=records($t,'salary_jobs');$changes=records($t,'salary_changes');
 if($action==='tables')return ['frames'=>$frames,'jobs'=>$jobs,'changes'=>$changes];
 if($action==='context'){$rows=[];foreach(records($t,'links') as $p){try{$q=salaryQuote($t,$p['salary']??null,$p,today());$current=$q+paidPay($q['cents'],$p,today());}catch(Fault $e){$current=['error'=>$e->getMessage()];}$projection=null;foreach($p['processes'] as $x)if($x['state']==='Em análise'&&isset($x['salaryTarget'])){$projection=forecast($t,$p,$x,$x['salaryTarget']['forecastDate']??today());break;}$rows[]=['linkId'=>$p['id'],'registration'=>$p['registration'],'name'=>$p['name'],'role'=>$p['role'],'planId'=>$p['planId'],'current'=>$current,'projection'=>$projection,'paidFunctions'=>$p['paidFunctions']??[]];}return ['frames'=>$frames,'jobs'=>$jobs,'changes'=>$changes,'functions'=>records($t,'paid_functions'),'salaries'=>$rows];}
 if($action==='frames'){if(!record($t,'plans',$b['planId']??''))throw new Fault('Plano não encontrado.');$r=save($t,'salary_frames',['id'=>uid(),'plan'=>$b['planId'],'name'=>need($b['name']??'','quadro',120)]);audit($t,'salary.frame.create',$r['id']);return ['id'=>$r['id']];}
 if($action==='jobs'){$frame=record($t,'salary_frames',$b['frameId']??'');if(!$frame||$frame['version']!==($b['version']??null))throw new Fault('Quadro alterado.',409);$plan=record($t,'plans',$frame['plan']);$source=null;foreach(salaryCatalog()['sources'] as $s)if($s['id']===($b['sourceId']??''))$source=$s;$groups=$b['groups']??[];if(!$source||$source['family']!==$plan['family']||!$groups||array_diff($groups,array_column($source['jobs'],'id')))throw new Fault('Selecione faixas do mesmo plano.');$loads=[];foreach($source['jobs'] as $g)if(in_array($g['id'],$groups,true)&&($g['workload']??null))$loads[]=$g['workload'];$loads=array_unique($loads);if(count($loads)>1)throw new Fault('Não misture jornadas no mesmo cargo.');$base=(int)($b['baseSequence']??0);if($base<0||$base>$frame['version'])throw new Fault('Versão base inválida.');$from=day($b['baseFrom']??'');foreach($changes as $e)if($e['frame']===$frame['id']&&$e['sequence']<=$base&&$e['effective']>$from)throw new Fault('A versão base incorpora uma mudança posterior à vigência.');$job=save($t,'salary_jobs',['id'=>uid(),'frame'=>$frame['id'],'name'=>need($b['name']??'','cargo',120),'source'=>$source['id'],'source_hash'=>$source['sha256'],'groups'=>['ids'=>$groups,'baseSequence'=>$base],'base_from'=>$from,'law'=>need($b['law']??'','fundamento da tabela',1000),'workload'=>array_values($loads)[0]??null]);save($t,'salary_frames',$frame,$frame['version']);audit($t,'salary.job.register',$job['id']);return ['id'=>$job['id']];}
 if($action==='adjust'){$frame=record($t,'salary_frames',$b['frameId']??'');if(!$frame||$frame['version']!==($b['version']??null))throw new Fault('Quadro alterado.',409);$kind=$b['kind']??'';if(!in_array($kind,['annual','exception']))throw new Fault('Tipo de atualização inválido.');if($kind==='annual'&&(!empty($b['jobId'])||!empty($b['jobIds'])||!empty($b['groups'])))throw new Fault('Revisão anual deve alcançar todo o quadro.');$job=null;if($kind==='exception'){$job=record($t,'salary_jobs',$b['jobId']??'');if(!$job||$job['frame']!==$frame['id'])throw new Fault('Selecione o cargo do quadro.');}$from=day($b['effective']??'');foreach($changes as $e)if($kind==='annual'&&$e['kind']==='annual'&&$e['frame']===$frame['id']&&$e['year']===(int)substr($from,0,4))throw new Fault('Já existe revisão anual neste exercício.');$frame=save($t,'salary_frames',$frame,$frame['version']);$r=save($t,'salary_changes',['id'=>uid(),'frame'=>$frame['id'],'job'=>$job['id']??null,'kind'=>$kind,'rate'=>percentage($b['percent']??''),'effective'=>$from,'year'=>(int)substr($from,0,4),'law'=>need($b['law']??'',$kind==='exception'?'lei específica do cargo':'fundamento da revisão anual',1000),'sequence'=>$frame['version'],'actor'=>$u['id'],'created'=>date(DATE_ATOM)]);audit($t,'salary.adjust.'.$kind,$r['id']);return ['id'=>$r['id'],'affectedJobs'=>$job?1:count(array_filter($jobs,fn($j)=>$j['frame']===$frame['id']))];}
 if($action==='mapping'){$p=linkFor($u,$b['linkId']??'');if(($b['checked']??false)!==true)throw new Fault('Confirme cargo, jornada, enquadramento e vigência.');$process=null;$idx=null;if(($b['position']??'')==='target'){foreach($p['processes'] as $i=>$x)if($x['id']===($b['processId']??'')&&$x['state']==='Em análise'){$process=$x;$idx=$i;}if(!$process)throw new Fault('Selecione um processo em análise.');}elseif(($b['position']??'')!=='current')throw new Fault('Associação inválida.');$map=['jobId'=>need($b['jobId']??'','cargo',64),'groupId'=>need($b['groupId']??'','faixa',64),'rowIndex'=>(int)($b['rowIndex']??-1),'context'=>salaryContextKey($p),'target'=>$process?j([$process['id'],$process['targetLevel'],$process['targetStage'],$process['type']]):null,'forecastDate'=>$process?day($b['effect']??''):null,'basis'=>need($b['basis']??'','fundamento da associação',1000),'actor'=>$u['id']];salaryQuote($t,$map,$p,$process?$map['forecastDate']:today(),$process);if($process)$p['processes'][$idx]['salaryTarget']=$map;else $p['salary']=$map;updateLink($u,$p,(int)($b['version']??0),'salary.mapping');return ['ok'=>true];}
 if($action==='forecast'){$p=linkFor($u,$b['linkId']??'');$x=null;foreach($p['processes'] as $r)if($r['id']===($b['processId']??''))$x=$r;return forecast($t,$p,$x,day($b['effect']??''));}
 if($action==='function-catalogue')return ['functions'=>array_values(array_filter(records($t,'paid_functions'),fn($f)=>($f['state']??'active')!=='deleted'))];
 if($action==='functions'){if($method!=='POST')throw new Fault('Método não permitido.',405);return savePaidFunction($u,$b);}
 if($action==='function-status'){if($method!=='POST')throw new Fault('Método não permitido.',405);return paidFunctionStatus($u,$b);}
 if(in_array($action,['designate','end-function','review-function'])){$p=linkFor($u,$b['linkId']??'');$p['paidFunctions']??=[];if($action==='designate'){$f=record($t,'paid_functions',$b['functionId']??'');if(!$f||($f['state']??'active')!=='active')throw new Fault('Função indisponível para novas designações.');$start=day($b['start']??'');$end=empty($b['end'])?null:day($b['end']);if($start<$p['admission']||$start<$f['from']||$end&&$end<$start||($f['until']??null)&&(!$end||$end>$f['until']))throw new Fault('Período fora da vigência ou da matrícula.');foreach($p['paidFunctions'] as $a)if($start<=($a['end']?:'9999-12-31')&&(!$end||$a['start']<=$end))throw new Fault('Existe função remunerada no período. Encerre a anterior.');$effect=$b['careerEffect']??'';if(!in_array($effect,['normal','suspend','special','unreviewed']))throw new Fault('Efeito funcional inválido.');$p['paidFunctions'][]=['id'=>uid(),'functionId'=>$f['id'],'snapshot'=>$f,'start'=>$start,'end'=>$end,'act'=>need($b['act']??'','ato',500),'careerEffect'=>$effect,'careerBasis'=>$effect==='unreviewed'?'':need($b['careerBasis']??'','fundamento do efeito',1000)];}else{$idx=array_search($b['assignmentId']??'',array_column($p['paidFunctions'],'id'),true);if($idx===false)throw new Fault('Designação não encontrada.');$a=&$p['paidFunctions'][$idx];if($action==='end-function'){$end=day($b['end']??'');if($end<$a['start']||$a['end']&&$end>$a['end'])throw new Fault('Data de encerramento inválida.');$a['end']=$end;$a['endAct']=need($b['act']??'','ato de encerramento',500);}else{if(!in_array($b['careerEffect']??'',['normal','suspend','special']))throw new Fault('Efeito inválido.');$a['previousAnalysis'][]=['effect'=>$a['careerEffect'],'basis'=>$a['careerBasis']];$a['careerEffect']=$b['careerEffect'];$a['careerBasis']=need($b['careerBasis']??'','fundamento do efeito',1000);}unset($a);}event($p,$u,'Função remunerada atualizada',$action);updateLink($u,$p,(int)($b['version']??0),'function.'.$action);return ['ok'=>true];}
 throw new Fault('Operação salarial não encontrada.',404);
}
